<body>
<div class="app">
    <h1>💸 expense tracker</h1>

    <!-- entry form -->
    <form id="expense-form" class="form-grid" autocomplete="off">
        <div class="form-field">
            <label for="amount">amount</label>
            <input type="number" id="amount" step="0.01" min="0" placeholder="0.00" required>
        </div>
        <div class="form-field">
            <label for="category">category</label>
            <select id="category">
                <option value="groceries">groceries</option>
                <option value="transport">transport</option>
                <option value="bills">bills</option>
                <option value="fun">fun</option>
            </select>
        </div>
        <div class="form-field">
            <label for="date">date</label>
            <input type="date" id="date" required>
        </div>
        <div class="form-field">
            <label for="note">note (optional)</label>
            <input type="text" id="note" placeholder="coffee, rent...">
        </div>
        <button type="submit" id="add-expense" class="btn">+ add</button>
    </form>

    <!-- error message -->
    <div id="form-error" class="error-msg" style="display: none;"></div>

    <!-- filters -->
    <div class="filters">
        <div class="filter-group">
            <label for="filter-category">category</label>
            <select id="filter-category">
                <option value="all">all</option>
                <option value="groceries">groceries</option>
                <option value="transport">transport</option>
                <option value="bills">bills</option>
                <option value="fun">fun</option>
            </select>
        </div>
        <div class="filter-group">
            <label for="filter-from">from</label>
            <input type="date" id="filter-from">
        </div>
        <div class="filter-group">
            <label for="filter-to">to</label>
            <input type="date" id="filter-to">
        </div>
    </div>

    <!-- summary -->
    <div class="summary">
        <span class="total-label">visible total</span>
        <span class="total-value" id="total">0.00</span>
    </div>

    <!-- per-category totals -->
    <div class="cat-summary" id="cat-summary-container">
        <span class="cat-item"><span data-cat="groceries" class="cat-total">0.00</span> groceries</span>
        <span class="cat-item"><span data-cat="transport" class="cat-total">0.00</span> transport</span>
        <span class="cat-item"><span data-cat="bills" class="cat-total">0.00</span> bills</span>
        <span class="cat-item"><span data-cat="fun" class="cat-total">0.00</span> fun</span>
    </div>

    <!-- expense list -->
    <div id="expense-list" class="expense-list"></div>
</div>

<script>
    (function() {
        // ---------- state ----------
        let expenses = [];  // each: {id, amount, category, date, note}

        // ---------- DOM refs ----------
        const form = document.getElementById('expense-form');
        const amountInput = document.getElementById('amount');
        const categorySelect = document.getElementById('category');
        const dateInput = document.getElementById('date');
        const noteInput = document.getElementById('note');
        const formError = document.getElementById('form-error');

        const filterCategory = document.getElementById('filter-category');
        const filterFrom = document.getElementById('filter-from');
        const filterTo = document.getElementById('filter-to');

        const totalEl = document.getElementById('total');
        const catTotalEls = document.querySelectorAll('.cat-total');
        const expenseListEl = document.getElementById('expense-list');

        // ---------- helpers ----------
        function formatMoney(value) {
            return Number(value).toFixed(2);
        }

        function getVisibleExpenses() {
            const cat = filterCategory.value;
            const from = filterFrom.value; // '' if empty
            const to = filterTo.value;

            return expenses.filter(exp => {
                // category filter
                if (cat !== 'all' && exp.category !== cat) return false;

                // date range filter
                if (from && exp.date < from) return false;
                if (to && exp.date > to) return false;

                return true;
            });
        }

        // ---------- render list & summary ----------
        function render() {
            const visible = getVisibleExpenses();

            // sort newest first (by date descending, then by id desc for stability)
            const sorted = [...visible].sort((a, b) => {
                if (a.date !== b.date) return b.date.localeCompare(a.date);
                return b.id - a.id; // newer id first
            });

            // build list
            if (sorted.length === 0) {
                expenseListEl.innerHTML = '<div class="empty-message">no expenses match</div>';
            } else {
                let html = '';
                for (const exp of sorted) {
                    html += `
                        <div class="expense" data-id="${exp.id}">
                            <div class="expense-info">
                                <span class="exp-amount">$${formatMoney(exp.amount)}</span>
                                <span class="exp-cat">${exp.category}</span>
                                <span class="exp-date">${exp.date}</span>
                                ${exp.note ? `<span style="color:#64748b; font-size:0.8rem;">“${escapeHtml(exp.note)}”</span>` : ''}
                            </div>
                            <button class="exp-del" data-id="${exp.id}" aria-label="delete">✕</button>
                        </div>
                    `;
                }
                expenseListEl.innerHTML = html;
            }

            // update total (visible)
            const total = visible.reduce((sum, e) => sum + e.amount, 0);
            totalEl.textContent = formatMoney(total);

            // update per-category totals (visible)
            const catTotals = {
                groceries: 0,
                transport: 0,
                bills: 0,
                fun: 0
            };
            for (const exp of visible) {
                if (catTotals.hasOwnProperty(exp.category)) {
                    catTotals[exp.category] += exp.amount;
                }
            }
            // update DOM elements
            catTotalEls.forEach(el => {
                const cat = el.getAttribute('data-cat');
                if (cat && catTotals.hasOwnProperty(cat)) {
                    el.textContent = formatMoney(catTotals[cat]);
                }
            });
        }

        // simple escape for note (prevent HTML injection)
        function escapeHtml(str) {
            const div = document.createElement('div');
            div.textContent = str;
            return div.innerHTML;
        }

        // ---------- persistence ----------
        function saveToLocalStorage() {
            localStorage.setItem('expenses_tracker', JSON.stringify(expenses));
        }

        function loadFromLocalStorage() {
            const stored = localStorage.getItem('expenses_tracker');
            if (stored) {
                try {
                    const parsed = JSON.parse(stored);
                    if (Array.isArray(parsed)) {
                        expenses = parsed.filter(e => e && typeof e.amount === 'number' && e.category && e.date);
                        // ensure id exists
                        expenses.forEach((e, idx) => {
                            if (!e.id) e.id = Date.now() + idx;
                        });
                    }
                } catch (e) {
                    expenses = [];
                }
            }
        }

        // ---------- add expense ----------
        function addExpense(event) {
            event.preventDefault();

            // get raw values
            const amountRaw = amountInput.value.trim();
            const category = categorySelect.value;
            const date = dateInput.value;
            const note = noteInput.value.trim();

            // validation
            let errorMsg = '';
            if (amountRaw === '') {
                errorMsg = 'Amount is required.';
            } else {
                const amountNum = Number(amountRaw);
                if (isNaN(amountNum) || !isFinite(amountNum)) {
                    errorMsg = 'Amount must be a valid number.';
                } else if (amountNum <= 0) {
                    errorMsg = 'Amount must be greater than zero.';
                }
            }
            if (!date) {
                errorMsg = errorMsg ? errorMsg + ' Date is required.' : 'Date is required.';
            }

            if (errorMsg) {
                formError.textContent = errorMsg;
                formError.style.display = 'block';
                return; // do not add
            }

            // valid: clear error
            formError.textContent = '';
            formError.style.display = 'none';

            // build expense object
            const amountNum = Number(amountRaw);
            const newExpense = {
                id: Date.now() + Math.floor(Math.random() * 1000),
                amount: amountNum,
                category: category,
                date: date,
                note: note || ''
            };

            expenses.push(newExpense);
            saveToLocalStorage();
            render();

            // reset amount field (and optionally note? spec says resets amount field)
            amountInput.value = '';
            // keep category/date as is, but we can reset date? spec only says amount field reset.
            // we'll leave date and category as user convenience.
            // but also clear note? not required, but we can leave it.
            // focus amount
            amountInput.focus();
        }

        // ---------- delete expense ----------
        function deleteExpense(id) {
            expenses = expenses.filter(e => e.id !== id);
            saveToLocalStorage();
            render();
        }

        // ---------- event delegation for delete ----------
        expenseListEl.addEventListener('click', (e) => {
            const delBtn = e.target.closest('.exp-del');
            if (delBtn) {
                const id = Number(delBtn.getAttribute('data-id'));
                deleteExpense(id);
            }
        });

        // ---------- filter change ----------
        function onFilterChange() {
            render();
        }

        // ---------- init ----------
        function init() {
            loadFromLocalStorage();
            // set default date to today? not required but helpful
            if (!dateInput.value) {
                const today = new Date().toISOString().split('T')[0];
                dateInput.value = today;
            }
            // attach listeners
            form.addEventListener('submit', addExpenseapsed); // placeholder, will replace
            // re-attach properly
            form.removeEventListener('submit', addExpenseapsed);
            form.addEventListener('submit', addExpense);

            filterCategory.addEventListener('change', onFilterChange);
            filterFrom.addEventListener('change', onFilterChange);
            filterTo.addEventListener('change', onFilterChange);

            // initial render
            render();
        }

        // temp fix: remove accidental listener
        function addExpenseapsed(e) { e.preventDefault(); }

        // start
        init();
    })();
</script>
</body>
</html>
